pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual after placing the item
    let mut score = post_residual as f64;

    // 1) Aggressive 2‑step lookahead: if the next item will fit in this bin,
    // reward heavily (lower score)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 1_000.0;
    }

    // 2) If this bin is the only one that can hold the current item, give it a bonus
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // 3) Balance the residual of this bin against the mean residual of all open bins
    let diff = (post_residual as f64 - mean_residual).abs();
    score -= 10.0 / (diff + 1.0); // closer to mean -> lower score

    // 4) Near the end of the stream, encourage tighter packing (lower score)
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= 50.0;
    }

    // 5) Penalize opening a new bin unless it is the only viable option
    if bin_residual == bin_capacity {
        // This call is for a brand‑new empty bin
        if fitting_bins_count == 0 {
            // No existing bin can fit the item – we must open a new bin
            score -= 10.0;
        } else {
            // Prefer using an existing bin over opening a new one
            score += 200.0;
        }
    }

    // 6) Small penalty if we already have many open bins to discourage fragmentation
    if open_bins_count > 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placement
    let mut score = post_residual as f64;

    // Penalize dead space that cannot accommodate the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap before we can place the next item
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 2.0; // weight 2.0
        } else {
            // Small bonus for leaving more space than needed
            score -= ((post_residual - next_item_size) as f64) * 0.5;
        }
    }

    // Pressure from many open bins: prefer to use existing bins
    score += (open_bins_count as f64) * 0.1;

    // If this bin is the only one that can fit the item, heavily favor it
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New bin candidate: penalize unless no open bins or no fitting bins exist
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // We already have a fitting open bin, avoid opening a new one
            score += 10.0;
        } else {
            // We must open a new bin, give a small bonus to encourage it
            score -= 2.0;
        }
    }

    // Adjust based on mean residual of all open bins
    if mean_residual < 20.0 {
        // When overall residual is low, favor bins with higher residual
        score -= (post_residual as f64) * 0.01;
    } else {
        // When overall residual is high, favor bins with lower residual
        score += (post_residual as f64) * 0.01;
    }

    // Optionally, add a tiny factor to encourage earlier decisions in the stream
    let progression = step_index as f64 / total_items.max(1) as f64;
    score += progression * 0.05;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised stream progress
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    // Core variables as f64
    let r = post_residual as f64;                 // residual after placing the item
    let m = mean_residual;                       // mean residual of all open bins
    let f = fitting_bins_count as f64;           // number of open bins that can fit the item
    let n = next_item_size as f64;               // size of the next item (0 if none)
    let o = open_bins_count as f64;              // current number of open bins

    // Smooth polynomial scoring
    let mut score = r
        // Penalise large residuals early in the stream
        - r.powi(2) * (1.0 - progress)
        // Prefer bins with lower mean residual as the stream proceeds
        - m * progress
        // Reward the last fitting bin (f close to 1) with a smooth penalty
        - (1.0 / (1.0 + (f - 1.0).powi(2))) * 50.0
        // Penalise bins that leave too little space for the next item
        + (1.0 / (1.0 + ((n - r).powi(2)))) * 30.0
        // Penalise keeping many open bins, increasing penalty later in the stream
        + o.powi(2) * 0.1 * progress;

    // Final score
    score
}

