pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: lower residual is better
    let mut score = post_residual as f64;

    // Aggressive 2‑step lookahead: penalize bins that cannot fit the next item,
    // reward bins that leave just enough space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // cannot fit the next item – heavy penalty
            score += ((next_item_size - post_residual) as f64) * 5.0;
        } else {
            // can fit – reward by reducing score
            score -= ((post_residual - next_item_size) as f64) * 0.5;
        }
    }

    // Penalize deviation from the mean residual (quadratic to discourage large swings)
    let diff = post_residual as f64 - mean_residual;
    score += diff.abs().powi(2) * 0.01;

    // If this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2000.0;
    }

    // Avoid opening a new bin when an existing one can accept the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 2000.0;
    }

    // Slightly penalize having many open bins (encouraging closure)
    score += (open_bins_count as f64) * 0.1;

    // Progress‑based penalty: as we near the end, prefer tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score starts with the residual after placing the item
    let mut score = post_residual as f64;

    // Reward for actually using space: larger items get a slight bonus
    score -= (item_size as f64) * 0.25;

    // Balance the residual relative to the current mean residual
    if mean_residual > 0.0 {
        let diff = (post_residual as f64 - mean_residual).abs();
        // Closer to mean -> larger reward
        let balanced = 1.0 / (1.0 + diff);
        score -= balanced * 5.0;
    }

    // Penalize bins that leave far more space than the average
    if mean_residual > 0.0 && post_residual as f64 > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Look‑ahead: if the next item will not fit, penalise; otherwise, reward tight fit
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 10.0; // next item won't fit here
        } else if post_residual <= next_item_size + 5 {
            score -= 5.0; // residual close enough to accommodate next item
        }
    }

    // New‑bin candidate: if the bin is empty, give a bonus that favours opening a new bin
    if bin_residual == bin_capacity {
        score -= (item_size as f64) * 0.2 + (open_bins_count as f64) * 0.5;
    }

    // Penalise open bins count (fewer open bins is better)
    score += (open_bins_count as f64) * 0.1;

    // Penalise the number of fitting bins (more options → less priority)
    score += (fitting_bins_count as f64) * 0.3;

    // Dynamic time horizon: near the end of the stream, tighten packing
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += progress * 5.0;

    // Last chance fit bonus: if this is the only bin that can accept the item, reward it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Ensure the score is non‑negative
    if score < 0.0 {
        score = 0.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual left after placing the item
    let mut score = post_residual as f64;

    // 1. Look‑ahead reward/penalty based on next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: we can fit the next item exactly or with room
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Bad: we will create a dead space that cannot fit the next item
            score += ((next_item_size - post_residual) as f64) * 2.0;
        }
    }

    // 2. Reward closeness to the mean residual (balance the bins)
    score -= ((post_residual as f64 - mean_residual).abs()) * 0.5;

    // 3. Penalize opening a brand new bin when a suitable bin already exists
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // 4. If only one bin can accept the item, strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 5. Adjust for stream progress: early on we want to leave space,
    //    later we want to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.5 {
        // Early: keep residual small
        score += (post_residual as f64) * 0.1;
    } else {
        // Late: keep residual large to reduce new bin openings
        score -= (post_residual as f64) * 0.1;
    }

    // 6. If many open bins exist, penalize using existing bins to reduce fragmentation
    if open_bins_count > 5 {
        score += 5.0;
    }

    score
}
